// DepotAgentServiceHandler is an implementation of the depot.agent.v1.DepotAgentService service.
type DepotAgentServiceHandler interface {
	// Creates a session and queues its first message. A sandbox starts for it within a minute.
	CreateSession(context.Context, *connect.Request[v1.CreateSessionRequest]) (*connect.Response[v1.CreateSessionResponse], error)
	// Queues a message for a session. A retry with the same `clientRequestId` returns the original.
	SendInput(context.Context, *connect.Request[v1.SendInputRequest]) (*connect.Response[v1.SendInputResponse], error)
	// Returns a session and the latest view of its conversation.
	GetSession(context.Context, *connect.Request[v1.GetSessionRequest]) (*connect.Response[v1.GetSessionResponse], error)
	// Lists the organization's sessions, newest first.
	ListDepotAgentSessions(context.Context, *connect.Request[v1.ListDepotAgentSessionsRequest]) (*connect.Response[v1.ListDepotAgentSessionsResponse], error)
	// Streams the session's view each time it changes.
	WatchSession(context.Context, *connect.Request[v1.WatchSessionRequest], *connect.ServerStream[v1.WatchSessionResponse]) error
	// Queues an interrupt, which stops whatever the agent is doing before it reads further messages.
	InterruptSession(context.Context, *connect.Request[v1.InterruptSessionRequest]) (*connect.Response[v1.InterruptSessionResponse], error)
	// Archives a session. Its pending messages are cancelled and it never runs again.
	ArchiveSession(context.Context, *connect.Request[v1.ArchiveSessionRequest]) (*connect.Response[v1.ArchiveSessionResponse], error)
	// Creates a trigger, which turns outside events into messages on a session. A "webhook" trigger
	// returns its URL and signing secret; the secret is shown only in this response.
	CreateTrigger(context.Context, *connect.Request[v1.CreateTriggerRequest]) (*connect.Response[v1.CreateTriggerResponse], error)
	// Lists the organization's triggers, newest first.
	ListTriggers(context.Context, *connect.Request[v1.ListTriggersRequest]) (*connect.Response[v1.ListTriggersResponse], error)
	// Deletes a trigger. Its URL stops accepting deliveries; sessions it started are kept.
	DeleteTrigger(context.Context, *connect.Request[v1.DeleteTriggerRequest]) (*connect.Response[v1.DeleteTriggerResponse], error)
	// Prepares files to attach to a message. Returns an upload URL for each file Depot does not already
	// store; upload those, then pass the attachments to `CreateSession` or `SendInput`.
	PrepareAttachmentUploads(context.Context, *connect.Request[v1.PrepareAttachmentUploadsRequest]) (*connect.Response[v1.PrepareAttachmentUploadsResponse], error)
	// Stores a new version of a session's agent definition, which the agent loads before its next turn.
	// Sending the same content as the current version returns that version instead of storing a copy.
	// To roll back, get an earlier version and put it again.
	PutAgentDefinition(context.Context, *connect.Request[v1.PutAgentDefinitionRequest]) (*connect.Response[v1.PutAgentDefinitionResponse], error)
	// Returns one version of a session's agent definition. Default: the current version.
	GetAgentDefinition(context.Context, *connect.Request[v1.GetAgentDefinitionRequest]) (*connect.Response[v1.GetAgentDefinitionResponse], error)
	// Offers the caller's own MCP servers to a session and streams the agent's tool calls to them. The first
	// message is `attached`. Calls arrive only on turns answering a message the caller wrote, and the servers
	// leave the session when the stream ends. A newer stream for the same session, from anyone, replaces this
	// one and ends it with FAILED_PRECONDITION; reconnect after any other end. Requires a user token.
	PullLocalMcpCalls(context.Context, *connect.Request[v1.PullLocalMcpCallsRequest], *connect.ServerStream[v1.PullLocalMcpCallsResponse]) error
	// Answers one call from `PullLocalMcpCalls`. Answering the same call twice, or one that was cancelled,
	// succeeds and is ignored. Fails with FAILED_PRECONDITION once the stream the call came from has ended.
	RespondLocalMcpCall(context.Context, *connect.Request[v1.RespondLocalMcpCallRequest]) (*connect.Response[v1.RespondLocalMcpCallResponse], error)
	// Adds a remote MCP server. An organization server, which only an owner can add, serves every message
	// sent in the organization's sessions; a user server, which any member can add, serves only the messages
	// its creator sends. Depot calls the server on the agent's behalf, so its credentials never reach a sandbox.
	CreateMcpServer(context.Context, *connect.Request[v1.CreateMcpServerRequest]) (*connect.Response[v1.CreateMcpServerResponse], error)
	// Lists the organization's MCP servers, then the caller's own; newest first within each.
	ListMcpServers(context.Context, *connect.Request[v1.ListMcpServersRequest]) (*connect.Response[v1.ListMcpServersResponse], error)
	// Removes an MCP server: an organization server for an owner, a user server for its creator. Tool listings
	// taken after the delete leave it out, and later calls to it fail, even from a turn whose tools were listed
	// before. A call that is already being sent may still complete.
	DeleteMcpServer(context.Context, *connect.Request[v1.DeleteMcpServerRequest]) (*connect.Response[v1.DeleteMcpServerResponse], error)
	// Stores a token as an MCP server's credential, which Depot sends as `Authorization: Bearer`, or clears it.
	// Any member who can use the server sets their own; an owner can set the organization's for an organization
	// server. The token is never returned.
	SetMcpServerToken(context.Context, *connect.Request[v1.SetMcpServerTokenRequest]) (*connect.Response[v1.SetMcpServerTokenResponse], error)
	// Returns a URL that logs in to an MCP server with OAuth, for the caller to open in a browser. The login is
	// stored as the server's credential: the caller's own, or as an owner the organization's. Only the caller can
	// finish the login, with `FinishMcpLogin`, within 10 minutes.
	StartMcpLogin(context.Context, *connect.Request[v1.StartMcpLoginRequest]) (*connect.Response[v1.StartMcpLoginResponse], error)
	// Lists the organization's credentials, then the caller's own. Values are never returned.
	ListAgentCredentials(context.Context, *connect.Request[v1.ListAgentCredentialsRequest]) (*connect.Response[v1.ListAgentCredentialsResponse], error)
	// Stores a named credential, or replaces the one of the same name and scope. A `${secrets.NAME}` reference
	// in an MCP server's headers resolves to the credential of the member who sent the message, then the
	// organization's, then the CI secret NAME. Depot sends it only to its hosts, and never to a sandbox.
	SetAgentCredential(context.Context, *connect.Request[v1.SetAgentCredentialRequest]) (*connect.Response[v1.SetAgentCredentialResponse], error)
	// Deletes a named credential.
	DeleteAgentCredential(context.Context, *connect.Request[v1.DeleteAgentCredentialRequest]) (*connect.Response[v1.DeleteAgentCredentialResponse], error)
	// Runs one action on a plugin view: a button, select or form. The click is queued as a "plugin_call" message,
	// shown in the transcript, and handled by the plugin inside the sandbox. A retry with the same
	// `clientRequestId` returns the original.
	InvokeViewAction(context.Context, *connect.Request[v1.InvokeViewActionRequest]) (*connect.Response[v1.InvokeViewActionResponse], error)
}

